using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;
using System.Linq;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var ts = EditorSceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            var text = "";
            foreach (float x in new[]{770f, 778f, 785f, 792f})
                foreach (float z in new[]{275f, 282f, 290f, 298f})
                {
                    var hits = Physics.RaycastAll(new Vector3(x, 30, z), Vector3.down, 50).OrderByDescending(h => h.point.y);
                    text += x + "," + z + ": " + string.Join(" | ", hits.Take(5).Select(h => h.collider.name + " y=" + h.point.y + " n=" + h.normal.y)) + "\n";
                }

            foreach (var t in ts.Where(t => t.name == "CR_Ha" || t.name == "Minh_RegionalWalk_180cm"))
            {
                text += t.name + " parent=" + (t.parent ? t.parent.name : "") + "\n";
                foreach (var c in t.GetComponentsInChildren<Collider>(true))
                    text += "COL " + c.name + " " + c.bounds + "\n";
            }

            File.WriteAllText("Test/KetQua/investigation_r102/location.txt", text);
            result.Log(text);
        }
    }
}

